	["Mount"] = "Monture",
	["Mount vendor"] = "Vendeur de montures",
	["Move and resize the bars, the minimap and the chat window. Press Escape and choose Edit Mode; Trailhead cannot do this for you."] = "Déplacez et redimensionnez les barres, la minicarte et la fenêtre de discussion. Appuyez sur Échap et choisissez Mode Édition ; Trailhead ne peut pas le faire pour vous.",
	["Move between the four riders on a plan."] = "Alternez entre les quatre cavaliers selon un plan.",
	["Move out of his poison cloud. Save stuns for his frenzy. He is the last boss."] = "Sortez de son nuage de poison. Gardez les étourdissements pour sa frénésie. C'est le dernier boss.",
	["Mr. Smite and Edwin VanCleef each bring two hidden guards. Expect a surprise attack."] = "Mr. Smite et Edwin VanCleef amènent chacun deux gardes cachés. Attendez-vous à une attaque surprise.",
	["Much more Stamina in Bear Form, so you have more Health."] = "Beaucoup plus d'Endurance en Forme d'ours : plus de points de vie.",
	["Navy and gold, soft and rounded"] = "Bleu marine et or, doux et arrondi",
	["Near its limit"] = "Proche de sa limite",
	["Near the end, with his guards."] = "Vers la fin, avec ses gardes.",
	["Near the end."] = "Vers la fin.",
	["Near the entrance, past the bridge."] = "Près de l'entrée, après le pont.",
	["Near the start, a giant hound."] = "Au début, un chien géant.",
	["Near the start, with two worgen at his side."] = "Au début, avec deux worgens à ses côtés.",
	["Near the waterfall past Lord Serpentis."] = "Près de la cascade, après Lord Serpentis.",
	["Neck"] = "Cou",
	["Need if you will use it. Greed to sell it. Pass to skip."] = "Besoin si vous allez l'utiliser. Cupidité pour le vendre. Passer pour l'ignorer.",
	["Need, greed"] = "Besoin, cupidité",
	["Needs"] = "Prérequis",
